                                  '        finally:\n'
                                  "            state['active'] = False\n"
                                  '            _club_active_transaction.reset(token)\n'
                                  '\n'
                                  'def _club_tree_sha256(root):\n'
                                  '    root = Path(root)\n'
                                  '    if root.is_symlink() or root.resolve() != root:\n'
                                  "        raise ValueError('Symlinked finite club historical context')\n"
                                  '    result = {}\n'
                                  '    def failed(error):\n'
                                  "        raise ValueError('Unreadable finite club historical context') "
                                  'from error\n'
                                  '    for directory, subdirectories, files in _club_os.walk(root, '
                                  'onerror=failed):\n'
                                  '        for name in subdirectories + files:\n'
                                  '            if (Path(directory) / name).is_symlink():\n'
                                  "                raise ValueError('Symlink in finite club historical "
                                  "context')\n"
                                  '        subdirectories[:] = [name for name in subdirectories if name != '
                                  "'__pycache__']\n"
                                  '        for name in files:\n'
                                  '            path = Path(directory) / name\n'
                                  '            result[path.relative_to(root).as_posix()] = '
                                  'digest(path.read_bytes())\n'
                                  '    return result\n'
                                  '\n'
                                  '\n'
                                  '\n'
                                  '# Only the finite complete-source/AST-pinned pure declarations below '
                                  'bypass\n'
                                  '# reader reauthentication. Their implementation uses captured pure '
                                  'primitives,\n'
                                  '# never mutable historical module globals or arbitrary caller objects.\n'
                                  'import ast as _club_ast\n'
                                  'import hashlib as _club_hashlib\n'
                                  '_CLUB_PURE_ROWS = '
                                  "{('Tests/ContractChecks/test_branch_history_fixture_handshake.py', "
                                  "'digest'): {'kind': 'bytes_sha256', 'parameter': 'data', 'source_sha256': "
                                  "'50b76bfffc27cbd7a792c95d031f6fd8e49777b6241b96ed8c4c4773edc356cb', "
                                  '\'shape\': "FunctionDef(name=\'_pure\', args=arguments(posonlyargs=[], '
                                  "args=[arg(arg='_value')], kwonlyargs=[], kw_defaults=[], defaults=[]), "
                                  "body=[Return(value=Call(func=Attribute(value=Call(func=Attribute(value=Name(id='hashlib', "
                                  "ctx=Load()), attr='sha256', ctx=Load()), args=[Name(id='_value', "
                                  "ctx=Load())], keywords=[]), attr='hexdigest', ctx=Load()), args=[], "
                                  'keywords=[]))], decorator_list=[], type_params=[])"}, '
