                                  '      "after_sha256": '
                                  '"02acd81d49d370748da8c780447b771bc7913e8813a9c537e04509b233e266f1",\n'
                                  '      "hunks": [\n'
                                  '        {\n'
                                  '          "before": "        self.track = '
                                  'Array(normalized.prefix(track.count)); self.places = '
                                  'Array(normalized.dropFirst(track.count))\\n    }\\n}\\n",\n'
                                  '          "after": "        self.track = '
                                  'Array(normalized.prefix(track.count)); self.places = '
                                  'Array(normalized.dropFirst(track.count))\\n    }\\n}\\n\\n/// A bounded '
                                  'local display schedule; it never reads, changes or saves a '
                                  'route.\\npublic struct RoamRouteReplayPlan: Equatable {\\n    public '
                                  'static let intervalNanoseconds: UInt64 = 120_000_000\\n    public static '
                                  'let maximumFrames = 24\\n    public let counts: [Int]\\n    public '
                                  'init(segmentCount: Int) {\\n        let total = max(0, '
                                  'segmentCount)\\n        guard total > 0 else { counts = []; return '
                                  '}\\n        let frames = min(total, Self.maximumFrames)\\n        let '
                                  'step = total / frames + (total % frames == 0 ? 0 : 1)\\n        var '
                                  'result: [Int] = [], count = 0\\n        while count < total '
                                  '{\\n            count = total - count <= step ? total : count + '
                                  'step\\n            result.append(count)\\n        }\\n        counts = '
                                  'result\\n    }\\n}\\n\\n/// Value-only replay authority. Timers live in '
                                  'the SwiftUI detail presentation.\\n/// A context belongs to an exact '
                                  'reader/scope, complete record value and visible lifetime.\\npublic struct '
                                  'RoamRouteReplayState {\\n    public struct Owner: Equatable {\\n        '
                                  'public let readerID: ObjectIdentifier\\n        public let identity: '
                                  'RoamExperienceIdentity?\\n        public let storageKey: '
                                  'String?\\n        public let configured: Bool\\n        public let '
                                  'record: RoamHistoryRecord\\n        @MainActor public init(reader: any '
                                  'RoamExperienceReading, record: RoamHistoryRecord) {\\n            '
                                  'readerID = ObjectIdentifier(reader); identity = '
                                  'reader.identity\\n            storageKey = '
                                  'identity?.scope.storageKey\\n            configured = '
                                  'reader.isConfigured; self.record = record\\n        }\\n    }\\n    '
                                  'public struct Context: Equatable {\\n        fileprivate let owner: '
                                  'Owner\\n        fileprivate let generation: UUID\\n    }\\n    public '
                                  'enum Phase: Equatable { case ready, playing, completed }\\n    public '
                                  'private(set) var phase: Phase = .ready\\n    public private(set) var '
                                  'totalSegments = 0\\n    /// nil means the unchanged full static sketch, '
                                  'including non-replay callers.\\n    public private(set) var '
                                  'visibleSegments: Int?\\n    private var owner: Owner?\\n    private var '
                                  'active = false\\n    private var reduceMotion = false\\n    private var '
                                  'generation = UUID()\\n    public init() {}\\n    public var progress: '
                                  'Double {\\n        guard totalSegments > 0 else { return 0 }\\n        '
                                  'return Double(visibleSegments ?? totalSegments) / '
                                  'Double(totalSegments)\\n    }\\n    public var plan: RoamRouteReplayPlan '
                                  '{ .init(segmentCount: totalSegments) }\\n    public mutating func '
                                  'update(owner: Owner, active: Bool, reduceMotion: Bool) {\\n        if '
                                  'self.owner != owner || self.active != active {\\n            generation = '
                                  'UUID(); phase = .ready; visibleSegments = nil\\n            let points = '
                                  'RoamRouteSketch(track: owner.record.track, places: '
                                  'owner.record.pois.map(\\\\.point)).track\\n            let hasLine = '
                                  'zip(points, points.dropFirst()).contains { pair in pair.0 != pair.1 '
                                  '}\\n            totalSegments = hasLine ? max(0, points.count - 1) : '
                                  '0\\n        }\\n        self.owner = owner; self.active = active; '
                                  'self.reduceMotion = reduceMotion\\n        if reduceMotion && phase == '
                                  '.playing { complete() }\\n    }\\n    public func context(for current: '
                                  'Owner) -> Context? {\\n        guard active, owner == current, '
                                  'totalSegments > 0 else { return nil }\\n        return Context(owner: '
                                  'current, generation: generation)\\n    }\\n    public func accepts(_ '
                                  'context: Context, current: Owner) -> Bool {\\n        self.context(for: '
                                  'current) == context\\n    }\\n    @discardableResult public mutating func '
                                  'start(in context: Context, current: Owner) -> Context? {\\n        guard '
                                  'accepts(context, current: current), phase != .playing else { return nil '
                                  '}\\n        generation = UUID()\\n        if reduceMotion { phase = '
                                  '.completed; visibleSegments = nil; return nil }\\n        phase = '
                                  '.playing; visibleSegments = 0\\n        return self.context(for: '
                                  'current)\\n    }\\n    public mutating func advance(to count: Int, in '
                                  'context: Context, current: Owner) {\\n        guard accepts(context, '
                                  'current: current), phase == .playing else { return }\\n        let '
                                  'bounded = min(totalSegments, max(0, count))\\n        guard bounded >= '
                                  '(visibleSegments ?? 0) else { return }\\n        visibleSegments = '
                                  'bounded\\n        if bounded == totalSegments { complete() }\\n    '
                                  '}\\n    public mutating func skip(in context: Context, current: Owner) '
                                  '{\\n        guard accepts(context, current: current), phase == .playing '
                                  'else { return }\\n        complete()\\n    }\\n    private mutating func '
                                  'complete() {\\n        generation = UUID(); phase = .completed; '
                                  'visibleSegments = nil\\n    }\\n}\\n"\n'
                                  '        },\n'
                                  '        {\n'
                                  '          "before": "        generation = UUID(); phase = .completed; '
                                  'visibleSegments = nil\\n    }\\n}\\n",\n'
                                  '          "after": "        generation = UUID(); phase = .completed; '
                                  'visibleSegments = nil\\n    }\\n}\\n\\n/// P128 local share projection '
                                  'only. Historical records remain unchanged.\\n/// Saved tracks are '
                                  'simplified, so clip by polyline length rather than sample count.\\npublic '
                                  'enum RoamShareRoutePrivacy {\\n    public static let endpointFraction = '
                                  '0.1\\n\\n    public static func clippedTrack(_ track: [RoamHistoryPoint]) '
                                  '-> [RoamHistoryPoint] {\\n        guard track.count >= 2 else { return [] '
                                  '}\\n        var lengths: [Double] = []\\n        for index in '
                                  '1..<track.count {\\n            let a = track[index - 1], b = '
                                  'track[index]\\n            // A schematic cannot safely interpolate a '
                                  'longitude wrap. Hide it rather than\\n            // drawing a '
                                  'trans-world segment or returning the original endpoints.\\n            '
                                  'guard abs(b.lng - a.lng) <= 180 else { return [] }\\n            '
                                  'lengths.append(RoamExperienceMath.distanceMeters(a.coordinate, '
                                  'b.coordinate))\\n        }\\n        let total = lengths.reduce(0, '
                                  '+)\\n        guard total.isFinite, total > 0 else { return [] }\\n        '
                                  'let start = total * endpointFraction, end = total - start\\n        var '
                                  'travelled = 0.0\\n        var result: [RoamHistoryPoint] = []\\n        '
                                  'for index in 1..<track.count {\\n            let length = lengths[index - '
                                  '1], next = travelled + length\\n            if length > 0, next > start, '
                                  'travelled < end {\\n                let a = track[index - 1], b = '
                                  'track[index]\\n                func interpolate(_ distance: Double) -> '
                                  'RoamHistoryPoint? {\\n                    let fraction = min(1, max(0, '
                                  '(distance - travelled) / length))\\n                    guard let '
                                  'coordinate = RoamCoordinate(\\n                        latitude: a.lat + '
                                  '(b.lat - a.lat) * fraction,\\n                        longitude: a.lng + '
                                  '(b.lng - a.lng) * fraction\\n                    ) else { return nil '
                                  '}\\n                    return RoamHistoryPoint(coordinate: '
                                  'coordinate)\\n                }\\n                if result.isEmpty '
                                  '{\\n                    guard let point = interpolate(max(start, '
                                  'travelled)) else { return [] }\\n                    '
                                  'result.append(point)\\n                }\\n                guard let '
                                  'point = interpolate(min(end, next)) else { return [] }\\n                '
                                  'result.append(point)\\n            }\\n            travelled = '
                                  'next\\n            if travelled >= end { break }\\n        }\\n        '
                                  'guard result.count >= 2 else { return [] }\\n        // Interpolation may '
                                  'round back to an original endpoint for adjacent Doubles.\\n        // A '
                                  'nominal 10% calculation is not evidence that the exported endpoint '
                                  'moved.\\n        let startInset = '
                                  'RoamExperienceMath.distanceMeters(track[0].coordinate, '
                                  'result[0].coordinate)\\n        let endInset = '
                                  'RoamExperienceMath.distanceMeters(track[track.count - 1].coordinate, '
                                  'result[result.count - 1].coordinate)\\n        guard startInset.isFinite, '
                                  'startInset > 0, endInset.isFinite, endInset > 0 else { return [] '
                                  '}\\n        var retainedLength = 0.0\\n        for index in '
                                  '1..<result.count {\\n            retainedLength += '
                                  'RoamExperienceMath.distanceMeters(result[index - 1].coordinate, '
                                  'result[index].coordinate)\\n        }\\n        guard '
                                  'retainedLength.isFinite, retainedLength > 0 else { return [] }\\n        '
                                  'return result\\n    }\\n\\n    public static func sketch(for record: '
                                  'RoamHistoryRecord) -> RoamRouteSketch {\\n        // POIs could '
                                  'independently reveal the removed home/work endpoint. Do not export '
                                  'them.\\n        RoamRouteSketch(track: clippedTrack(record.track), '
                                  'places: [])\\n    }\\n}\\n"\n'
