  "            'Changed complete raw fixture selection')\n"
  '    require(hashlib.sha256(incoming[PATHS[3]]).hexdigest() == FIXTURE_TEST_SHA256,\n'
  "            'Changed complete fixture diagnostic tests')\n"
  '    fixture_test_preimage(incoming[PATHS[3]])\n'
  "    require(hashlib.sha256(encode(selection['creator_fixture_rejection']).encode()).hexdigest() == "
  'FIXTURE_LAYER_SHA256,\n'
  "            'Changed independently fixed fixture layer')\n"
  "    for row in FIXTURE_LAYER['payload']:\n"
  "        raw = incoming[row['path']]\n"
  "        require(hashlib.sha256(raw).hexdigest() == row['after_sha256'] and blob_id(raw) == "
  "row['after_blob'],\n"
  "                'Changed frozen fixture postimage: ' + row['path'])\n"
  "        if row['status'] == 'M': inverse_reviewed_repair(row, raw)\n"
  '        else:\n'
  "            require(row['status'] == 'A' and row['path'] == "
  "'tools/tests/test_creator_history_fixture_rejection.py'\n"
  "                    and row['before_sha256'] is None and row['before_blob'] is None and row['hunks'] == "
  '[],\n'
  "                    'Fixture addition has fabricated history')\n"
  '    return incoming\n',
